import { Readable, Writable } from "node:stream";
import * as acp from "@agentclientprotocol/sdk";

export default async function runClient(readable, writable) {
  const updates = [];
  const client = acp.client({ name: "ji-stage3-conformance" })
    .onNotification(acp.methods.client.session.update, ({ params }) => {
      updates.push(params);
    })
    .onRequest(acp.methods.client.session.requestPermission, ({ params }) => ({
      outcome: { outcome: "selected", optionId: params.options[0].optionId },
    }))
    .onRequest(acp.methods.client.fs.readTextFile, () => ({ content: "conformance" }))
    .onRequest(acp.methods.client.fs.writeTextFile, () => ({}))
    .onRequest(acp.methods.client.terminal.create, () => ({ terminalId: "terminal-1" }))
    .onRequest(acp.methods.client.terminal.output, () => ({ output: "", truncated: false }))
    .onRequest(acp.methods.client.terminal.waitForExit, () => ({ exitCode: 0 }))
    .onRequest(acp.methods.client.terminal.kill, () => ({}))
    .onRequest(acp.methods.client.terminal.release, () => ({}))
    .onRequest(acp.methods.client.elicitation.create, () => ({ action: "cancel" }));

  const stream = acp.ndJsonStream(Writable.toWeb(writable), Readable.toWeb(readable));
  return client.connectWith(stream, async (ctx) => {
    const initialized = await ctx.request(acp.methods.agent.initialize, {
      protocolVersion: acp.PROTOCOL_VERSION,
      clientCapabilities: {
        fs: { readTextFile: true, writeTextFile: true },
        terminal: true,
        elicitation: { form: {}, url: {} },
      },
      clientInfo: { name: "ji-stage3-conformance", version: "1.0.0" },
    });
    const cwd = process.cwd();
    const created = await ctx.request(acp.methods.agent.session.new, { cwd, mcpServers: [] });
    await ctx.request(acp.methods.agent.session.load, { sessionId: created.sessionId, cwd, mcpServers: [] });
    const stopped = await ctx.request(acp.methods.agent.session.prompt, {
      sessionId: created.sessionId,
      prompt: [{ type: "text", text: "stage3 conformance" }],
      _meta: { commandId: "stage3-ts-sdk" },
    });
    const listed = await ctx.request(acp.methods.agent.session.list, {});
    await ctx.request(acp.methods.agent.session.close, { sessionId: created.sessionId });
    return {
      ok: true,
      protocolVersion: initialized.protocolVersion,
      sessionId: created.sessionId,
      stopReason: stopped.stopReason,
      listed: listed.sessions.some((session) => session.sessionId === created.sessionId),
      updates: updates.map((value) => value.update.sessionUpdate),
    };
  });
}

if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1].replaceAll("\\", "/")}`).href) {
  const result = await runClient(process.stdin, process.stdout);
  process.stderr.write(`${JSON.stringify(result)}\n`);
}
